def tokenize(text):
    """Lowercase a text and split it on whitespace."""
    return text.lower().split()

def tokens(sentence):
    """Split a sentence into tokens on whitespace."""
    return sentence.split()

# count bigrams with a plain dictionary
counts = {}
for sent in corpus:
    toks = tokens(sent)
    for a, b in zip(toks, toks[1:]):
        counts[(a, b)] = counts.get((a, b), 0) + 1
print("count(the, cat) =", counts[("the", "cat")])

